export function resolveNoteUrl(noteId?: string, rawUrl?: string): string {
  const url = (rawUrl || "").trim();
  // If we already have a full valid external link
  if (url.startsWith("http://") || url.startsWith("https://") || url.startsWith("//")) {
    return url;
  }
  // If url is a placeholder like "PDF", "pdf", "URL", "link", etc.
  if (noteId && NOTE_HYPERLINKS_MAP[noteId]) {
    return NOTE_HYPERLINKS_MAP[noteId];
  }
  return url;
}

