/**
 * Returns the exact page count of the PDF document.
 * If 1-page, returns 1. If 4-page, returns 4, etc.
 */
export function getNotePageCount(noteId?: string, rawUrl?: string): number {
  if (noteId && NOTE_PAGE_COUNTS_MAP[noteId]) {
    return NOTE_PAGE_COUNTS_MAP[noteId];
  }
  const url = (rawUrl || "").toLowerCase();
  const match = url.match(/[#&?]pages?=(\d+)/);
  if (match) {
    return Math.max(1, parseInt(match[1], 10));
  }
  return 1;
}

